<?php
declare(strict_types=1);
require __DIR__ . '/includes/bootstrap.php';
require_login();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 require_role(['admin']); verify_csrf();
 $name=trim((string)($_POST['part_name']??''));$number=trim((string)($_POST['part_number']??''));$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$reorder=filter_var($_POST['reorder_level']??null,FILTER_VALIDATE_INT);$cost=trim((string)($_POST['unit_cost']??''));$supplier=trim((string)($_POST['supplier']??''));
 if($name===''||mb_strlen($name)>150||mb_strlen($number)>100||$qty===false||$qty<0||$reorder===false||$reorder<0||($cost!==''&&(!is_numeric($cost)||(float)$cost<0))||mb_strlen($supplier)>160)$error='Please check the spare part details.';
 else{$stmt=db()->prepare('INSERT INTO spare_parts(part_name,part_number,quantity,reorder_level,unit_cost,supplier) VALUES(?,?,?,?,?,?)');$stmt->execute([$name,$number?:null,$qty,$reorder,$cost===''?null:$cost,$supplier?:null]);audit('spare_part_created','Part '.$name);header('Location: parts.php?saved=1');exit;}
}
$parts=db()->query('SELECT * FROM spare_parts ORDER BY (quantity<=reorder_level) DESC,part_name')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Spare parts | Gaston Power</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="app-shell"><aside class="sidebar"><div class="side-brand"><span class="brand-mark">GP</span><div><strong>Gaston Power</strong><small>Maintenance Suite</small></div></div><nav><a href="dashboard.php">Overview</a><a href="generators.php">Generators</a><a href="customers.php">Customers</a><a href="maintenance.php">Maintenance</a><a class="active" href="parts.php">Spare parts</a><a href="change-password.php">Change password</a></nav><div class="side-bottom"><span><?=e($_SESSION['full_name']??'Staff')?></span><small><?=e(ucfirst($_SESSION['role']??''))?></small><form method="post" action="logout.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button class="logout">Sign out</button></form></div></aside><main class="main-content"><header class="topbar"><div><p class="eyebrow">INVENTORY / PARTS</p><h1>Spare parts</h1><p class="muted">Track stock levels and identify items that need reordering.</p></div><span class="role-chip"><?=count($parts)?> items</span></header><?php if(isset($_GET['saved'])):?><p class="success">Part added to inventory.</p><?php endif;?><?php if($error):?><p class="alert"><?=e($error)?></p><?php endif;?>
<?php if(($_SESSION['role']??'')==='admin'):?><section class="panel form-panel"><h2>Add spare part</h2><form method="post" class="record-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Part name<input name="part_name" maxlength="150" required placeholder="e.g. Oil filter"></label><label>Part number<input name="part_number" maxlength="100"></label><label>Quantity<input type="number" name="quantity" min="0" step="1" value="0" required></label><label>Reorder level<input type="number" name="reorder_level" min="0" step="1" value="2" required></label><label>Unit cost (KES)<input type="number" name="unit_cost" min="0" step="0.01"></label><label>Supplier<input name="supplier" maxlength="160"></label><div class="wide"><button class="button">Add part</button></div></form></section><?php endif;?>
<section class="panel"><div class="panel-heading"><div><h2>Stock register</h2><p class="muted">Low-stock items are highlighted.</p></div></div><?php if(!$parts):?><div class="empty-state"><h3>No spare parts recorded</h3><p>Add filters, belts, batteries and other parts used during servicing.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Part</th><th>Part number</th><th>Quantity</th><th>Reorder level</th><th>Unit cost</th><th>Supplier</th><th>Stock status</th></tr></thead><tbody><?php foreach($parts as $p):$low=(int)$p['quantity']<=(int)$p['reorder_level'];?><tr><td><?=e($p['part_name'])?></td><td><?=e($p['part_number']??'—')?></td><td><?=(int)$p['quantity']?></td><td><?=(int)$p['reorder_level']?></td><td><?=e($p['unit_cost']===null?'—':'KES '.number_format((float)$p['unit_cost'],2))?></td><td><?=e($p['supplier']??'—')?></td><td><span class="status <?=$low?'low-stock':''?>"><?=$low?'Reorder':'In stock'?></span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main></div></body></html>
